-- A16: per-project status prompt in its channel, office timezone, prompt dedupe table.
-- Generated by drizzle-kit, then edited by hand so it is safe on a DB with existing rows:
-- offices.timezone is added nullable, backfilled (UA -> Europe/Kyiv, PL -> Europe/Warsaw,
-- any other office -> Europe/Kyiv) and only then set NOT NULL.
CREATE TABLE "project_prompts" (
	"project_id" uuid NOT NULL,
	"prompt_date" date NOT NULL,
	"posted_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "project_prompts_pk" PRIMARY KEY("project_id","prompt_date")
);
